      "sha256": "1d13cde1c01a24a91901382b2669b4ce34108f8751b92b13a14cc7f53036317e",
      "size": [
        1280,
        1000
      ],
      "saw": "Full page: live panel 'Current queue state \u00b7 succeeded' with two 3x checks labelled Ready (full and compact consumers); matrix rows idle (Start triangle at 1x/3x in both consumers), running/paused/failed marked 'Missing asset' with their labels Working/Paused/Retry, succeeded with the check at 1x/3x in both consumers; coverage line '3 status assets are still missing: assets/working.png, assets/paused.png, assets/error-retry.png'."
    },
    {
      "path": "work/render-caller-01/view-004.png",
      "sha256": "dc9d6e930fd6b22025c70ca438863c513a864d47dd02dda12c239bdad687e7c1",
